DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_TRAINERRED' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_TRAINERRED_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_TEXT_1','Indigo Champion[NEWLINE]An irreplaceable veteran team and selected tactical tools[NEWLINE]Domination; Science from successful high-value combat[NEWLINE][NEWLINE]Train and preserve partners, maintain a diverse Champion Team, and take valuable fights without treating a rank as permission to ignore support. A dead partner''s Training and history are permanently lost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_TEXT_2','Use ordinary support troops and safe camps to develop the first veterans. Establish food, Production and the infrastructure needed to replace conventional losses. Select useful partners instead of filling every role with the same unit class.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_TEXT_3','Manage the roster, item cooldowns and Ace support. Check the highest rank''s actual effects: ranks replace earlier ranks rather than adding every listed benefit. Use strongest-fielded-type rewards only when the battle is genuinely favourable.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_TEXT_4','Prepare Mt. Silver around its real eligibility, withdrawal and return constraints. Keep a conventional defense while partners are unavailable, preserve legal return locations, and use the team as part of a complete army.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_TEXT_5','- Training and team support can develop unusually valuable surviving units.[NEWLINE]- Successful fights against an eligible strongest fielded type reward more than ordinary casualties.[NEWLINE]- Roster tools allow deliberate tactical roles and recovery planning.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_TEXT_6','- Death permanently removes individual Training and veteran history.[NEWLINE]- Team capacity and several active tools have gates or cooldowns.[NEWLINE]- A temporary withdrawal or a badly composed team can leave conventional cities exposed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_TEXT_7','- Focus a developed partner to completion rather than donating repeated survivable exchanges.[NEWLINE]- Deny easy strongest-type kills and isolate the team from its supporting units.[NEWLINE]- Apply pressure when the main partners are withdrawn or key abilities are cooling down.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_TEXT_8','- Adding the effects of every Training rank together.[NEWLINE]- Treating a replacement unit as if it inherits a dead partner''s Training.[NEWLINE]- Starting a withdrawal without checking the capital defense and later legal return space.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Supported partners can end an exchange before a Project attacker safely reaches its rewarding finish.[NEWLINE][NEWLINE]T1: Eliminating an elite roster member can create a serious recovery gap; an eligible strongest-fielded-type kill also rewards Red''s progression.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A coordinated early attacking window can kill valuable partners before the team has accumulated enough support.[NEWLINE][NEWLINE]The Filthy Realm: A well-positioned attack shutdown can expose several valuable team members at once.');
