INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_STRATEGY','Train and preserve partners, maintain a diverse Champion Team, and take valuable fights without treating a rank as permission to ignore support. A dead partner''s Training and history are permanently lost.[NEWLINE][NEWLINE]Use ordinary support troops and safe camps to develop the first veterans. Establish food, Production and the infrastructure needed to replace conventional losses. Select useful partners instead of filling every role with the same unit class.[NEWLINE][NEWLINE]Manage the roster, item cooldowns and Ace support. Check the highest rank''s actual effects: ranks replace earlier ranks rather than adding every listed benefit. Use strongest-fielded-type rewards only when the battle is genuinely favourable.[NEWLINE][NEWLINE]Prepare Mt. Silver around its real eligibility, withdrawal and return constraints. Keep a conventional defense while partners are unavailable, preserve legal return locations, and use the team as part of a complete army.');
