INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_LEADER_TEXT_2','Use ordinary support troops and safe camps to develop the first veterans. Establish food, Production and the infrastructure needed to replace conventional losses. Select useful partners instead of filling every role with the same unit class.[NEWLINE][NEWLINE]Manage the roster, item cooldowns and Ace support. Check the highest rank''s actual effects: ranks replace earlier ranks rather than adding every listed benefit. Use strongest-fielded-type rewards only when the battle is genuinely favourable.[NEWLINE][NEWLINE]Prepare Mt. Silver around its real eligibility, withdrawal and return constraints. Keep a conventional defense while partners are unavailable, preserve legal return locations, and use the team as part of a complete army.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_TRAINERRED_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Supported partners can end an exchange before a Project attacker safely reaches its rewarding finish.[NEWLINE][NEWLINE]T1: Eliminating an elite roster member can create a serious recovery gap; an eligible strongest-fielded-type kill also rewards Red''s progression.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A coordinated early attacking window can kill valuable partners before the team has accumulated enough support.[NEWLINE][NEWLINE]The Filthy Realm: A well-positioned attack shutdown can expose several valuable team members at once.');
